/**
 * Source-document registry (docs/DATA_DICTIONARY.md "Source-document record").
 * sourceIds match those generated by normalisation.service.js: mppcb-<year>-<festival>.
 * URLs and retrieval dates are taken from track-2-visarjan-ghat-watch/PROBLEM-STATEMENT.md.
 */

const RETRIEVED_AT = '2026-10-10';

const MPPCB_REPORTS = {
  2023: {
    title: 'MPPCB Idol Immersion Report 2023 (CPCB format)',
    sourceUrl: 'https://www.mppcb.mp.gov.in/proc/mon/Idol_immer._Report_23_CPCB.pdf',
    fileName: 'resources/Idol_immer._Report_23_CPCB.pdf',
  },
  2024: {
    title: 'MPPCB Ganesh and Durga Visarjan Report 2024',
    sourceUrl: 'https://www.mppcb.mp.gov.in/proc/mon/Ganesh_and_Durga_visarjan_report-2024.pdf',
    fileName: 'resources/Ganesh_and_Durga_visarjan_report-2024.pdf',
  },
  2025: {
    title: 'MPPCB Ganesh and Durga Visarjan Report 2025',
    sourceUrl: 'https://www.mppcb.mp.gov.in/proc/mon/Ganesh_and_Durga_visarjan_report-2025.pdf',
    fileName: 'resources/Ganesh_and_Durga_visarjan_report-2025.pdf',
  },
};

export const CPCB_CRITERIA_SOURCE = Object.freeze({
  sourceId: 'cpcb-water-quality-criteria',
  title: 'CPCB Water Quality Criteria (designated best use classes A–E)',
  publisher: 'Central Pollution Control Board',
  sourceUrl: 'https://cpcb.gov.in/water-quality-criteria/',
  retrievedAt: RETRIEVED_AT,
  fileName: 'data/cpcb_water_quality_criteria.csv',
  notes: 'Class B (outdoor bathing) is used as a comparison benchmark, not as a legal rule for idol immersion.',
});

/** Returns source metadata for an observation sourceId, or null if it is not a known MPPCB report. */
export function getSourceDocument(sourceId) {
  const match = /^mppcb-(\d{4})-(ganesh|durga)$/.exec(sourceId);
  if (!match) return null;
  const [, year, festival] = match;
  const report = MPPCB_REPORTS[year];
  if (!report) return null;
  const festivalName = festival === 'ganesh' ? 'Ganesh' : 'Durga';

  return {
    sourceId,
    title: `${report.title} — ${festivalName} tables`,
    publisher: 'Madhya Pradesh Pollution Control Board',
    sourceUrl: report.sourceUrl,
    retrievedAt: RETRIEVED_AT,
    fileName: report.fileName,
    year: Number(year),
    festival: festivalName,
    notes: 'Units are not printed in the report; units shown are the standard units for each test.',
  };
}
